(* [comment removed for export] *)
Definition zrun (g : Z * Z * Z) : bool := let '(beg, sz, szrz) := g in (sz =? szrz) && (0 <? sz) && (sz mod 8 =? 0).
Definition inrun (a n : Z) (g : Z * Z * Z) : bool := let '(beg, sz, szrz) := g in (beg <=? a) && (a + n <=? beg + sz).
(* [comment removed for export] *)
Definition aimg0b (a n : Z) : bool := (0 <=? n) && existsb (fun g => zrun g && inrun a n g) aglobals.
(* [comment removed for export] *)
Definition aglobb (a n : Z) : bool := (0 <=? n) && existsb (inrun a n) aglobals.
(* [comment removed for export] *)

Lemma aimg0_count : length (List.filter zrun aglobals) = 34%nat.  Proof. vm_compute. reflexivity. Qed.

(* [comment removed for export] *)
(* [comment removed for export] *)
Definition AImgSh0 (m : mem) (lo hi : Z) : Prop :=
  AIMG_LO <= lo /\ hi <= AIMG_TOP /\ forall x, lo <= x < hi -> mrd asegs m (wa (sh x)) = Some (b8 0).

Lemma AImgSh0_sub : forall m lo hi lo' hi', AImgSh0 m lo hi -> lo <= lo' -> hi' <= hi -> AImgSh0 m lo' hi'.
Proof. intros m lo hi lo' hi' (H0 & H1 & H) ? ?. split; [lia|]. split; [lia|]. intros x Hx. apply H. lia. Qed.

Lemma AImgSh0_accessible : forall m lo hi a n, AImgSh0 m lo hi -> lo <= a -> a + n <= hi -> accessible m a n.
Proof.
  intros m lo hi a n (H0 & H1 & H) Ha Hn. unfold accessible. unfold AIMG_LO, AIMG_TOP, AAPP_HI in *.
  split; [lia|]. split; [lia|]. intros x Hx. exists 0. split; [lia|]. split; [apply H; lia | left; reflexivity].
Qed.

(* [comment removed for export] *)
Lemma AImgSh0_read0 : forall m lo hi a x, AImgSh0 m lo hi -> lo <= a < hi -> x = wa (sh a) ->
  ov_read_bytes asegs m x 1 = Some [b8 0].
Proof.
  intros m lo hi a x (H0 & H1 & H) Ha ->. pose proof (H a Ha) as RD.
  rewrite ov_rdn. cbn [rdn]. unfold mrd in RD.
  destruct (m (wa (sh a))) as [b|] eqn:E.
  - inversion RD; subst. reflexivity.
  - destruct (seg_rom asegs (wa (sh a))) as [b|]; [| discriminate RD]. inversion RD; subst. reflexivity.
Qed.
Lemma AImgSh0_read0_sr : forall m lo hi a, AImgSh0 m lo hi -> lo <= a < hi ->
  ov_read_bytes asegs m (Z_to_bv 64 (Z.shiftr a 3 + 2147450880)) 1 = Some [b8 0].
Proof.
  intros m lo hi a SH Ha. apply (AImgSh0_read0 m lo hi a _ SH Ha).
  destruct SH as (H0 & _ & _). unfold AIMG_LO in H0. rewrite <- (sh_shiftr a) by lia. rewrite ASHADOW_BASE_val. reflexivity.
Qed.

