Lemma aglobals_entry_facts : forall beg sz szrz, In (beg, sz, szrz) aglobals ->
  AIMG_LO <= beg /\ beg + szrz <= AIMG_TOP /\ 0 <= sz /\ 8 * nsh sz <= szrz /\ szrz mod 8 = 0 /\ beg mod 8 = 0.
Proof. intros beg sz szrz IN. exact (proj1 (Forall_forall _ _) aglobals_facts _ IN). Qed.
