Lemma ACONST_img_accessible : forall m a n, ACONST m -> aimg0b a n = true -> accessible m a n.
Proof.
  intros m a n AC H. assert (Hn : 0 <= n) by (unfold aimg0b in H; apply andb_prop in H as [Hn _]; apply Z.leb_le in Hn; exact Hn).
  apply (AImgSh0_accessible m a (a + n) a n); [| lia | lia].
  apply ACONST_imgsh0; [exact AC|]. replace (a + n - a) with n by lia. exact H.
Qed.

