Lemma ACONST_img_shvis : forall m a n, ACONST m -> AIMG_LO + 64 <= a -> 0 <= n -> a + n + 64 <= AIMG_TOP -> shvis m a (a + n).
Proof. intros m a n AC H1 H2 H3. apply ACONST_shvis; [exact AC | lia | lia | lia]. Qed.
Lemma img_in_app_mem : forall a n, AIMG_LO <= a -> a + n <= AIMG_TOP -> in_app_mem a (a + n).
Proof. intros a n H1 H2. left. unfold AIMG_LO, AIMG_TOP in *. rewrite ASHADOW_BASE_val. lia. Qed.

